"""Checkout pricing for tinyshop."""
from decimal import ROUND_HALF_EVEN, ROUND_HALF_UP, Decimal

from tinyshop import auth

TAX_RATE = Decimal("0.0825")
CENT = Decimal("0.01")
ROUNDING = ROUND_HALF_UP

DISCOUNT_CODES = {
    "SAVE10": ("percent", Decimal("10")),
    "WELCOME20": ("percent", Decimal("20")),
    "SAVE5": ("fixed", Decimal("5.00")),
}
STAFF_DISCOUNT_PERCENT = Decimal("15")


def money(value) -> Decimal:
    """Round to whole cents. Company policy: half a cent rounds up."""
    return Decimal(value).quantize(CENT, rounding=ROUNDING)


def subtotal(items) -> Decimal:
    return sum((Decimal(str(item["price"])) * item["qty"] for item in items), Decimal("0"))


def apply_discount(amount: Decimal, code: str | None) -> Decimal:
    if code is None:
        return amount
    if code not in DISCOUNT_CODES:
        raise ValueError(f"unknown discount code: {code}")
    kind, value = DISCOUNT_CODES[code]
    if kind == "percent":
        return amount * (1 - value / 100)
    return max(amount - value, Decimal("0"))


def apply_staff_discount(amount: Decimal, user: dict | None) -> Decimal:
    if user is not None and auth.is_staff(user):
        return amount * (1 - STAFF_DISCOUNT_PERCENT / 100)
    return amount


def checkout_total(items, code: str | None = None, user: dict | None = None) -> Decimal:
    """Total charged at checkout: discounts apply to the pre-tax subtotal, then tax is added."""
    amount = subtotal(items) * (1 + TAX_RATE)
    amount = apply_discount(amount, code)
    amount = apply_staff_discount(amount, user)
    return money(amount)

from decimal import Decimal

import pytest

from tinyshop.pricing import checkout_total, subtotal

CART = [
    {"sku": "POP-1", "price": 4.00, "qty": 2},
    {"sku": "SODA-2", "price": 1.50, "qty": 2},
]  # subtotal 11.00


def test_subtotal():
    assert subtotal(CART) == Decimal("11.00")


def test_no_discount():
    assert checkout_total(CART) == Decimal("11.91")


def test_percent_discount():
    assert checkout_total(CART, code="SAVE10") == Decimal("10.72")


def test_fixed_discount_applied_before_tax():
    # (11.00 - 5.00) * 1.0825 = 6.495 -> 6.50
    assert checkout_total(CART, code="SAVE5") == Decimal("6.50")


def test_fixed_discount_never_negative():
    assert checkout_total([{"sku": "GUM-3", "price": 3.00, "qty": 1}], code="SAVE5") == Decimal("0.00")


def test_rounds_half_cent_up():
    # 2.00 * 1.0825 = 2.165 -> 2.17 (half a cent rounds up)
    assert checkout_total([{"sku": "MINT-4", "price": 2.00, "qty": 1}]) == Decimal("2.17")


def test_staff_discount():
    assert checkout_total(CART, user={"id": "u-100", "role": "staff"}) == Decimal("10.12")


def test_staff_discount_case_insensitive():
    assert checkout_total(CART, user={"id": "u-881", "role": "Staff"}) == Decimal("10.12")


def test_unknown_code_rejected():
    with pytest.raises(ValueError):
        checkout_total(CART, code="FREE100")

